async function calculate_basic_pay(frm) {

    console.clear();

    console.log("========== SALARY CALCULATION STARTED ==========");

    try {

        console.log("Employee:", frm.doc.employee);
        console.log("Start Date:", frm.doc.start_date);
        console.log("End Date:", frm.doc.end_date);

        if (!frm.doc.employee || !frm.doc.start_date || !frm.doc.end_date) {
            frappe.msgprint("Please select Employee, Start Date and End Date.");
            return;
        }

        // STEP 1: Fetch Site TimeSheet records

        console.log("STEP 1: Fetching Site TimeSheet records...");

        let response = await frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Site TimeSheet",
                filters: {
                    custom_emp_name: frm.doc.employee,
                    custom_date: [
                        "between",
                        [frm.doc.start_date, frm.doc.end_date]
                    ]
                },
                fields: [
                    "name",
                    "custom_emp_name",
                    "custom_date",
                    "custom_total_hrs",
                    "custom_ot_day_hrs",
                    "custom_ot_night_hrs",
                    "custom_rest_hrs"
                ],
                limit_page_length: 5000
            }
        });

        let records = response.message || [];

        console.log("Site TimeSheet Records Found:", records.length);
        console.table(records);



        // STEP 2: Convert Time Fields into Decimal Hours and Calculate Totals

        function time_to_hours(value) {

            if (!value) return 0;

            let parts = String(value).split(":");

            let hours = flt(parts[0] || 0);
            let minutes = flt(parts[1] || 0);
            let seconds = flt(parts[2] || 0);

            return hours + (minutes / 60) + (seconds / 3600);
        }

        let total_working_hours = 0;
        let total_ot_day_hours = 0;
        let total_ot_night_hours = 0;
        let total_rest_day_hours = 0;

        for (let row of records) {

            let working_hours = time_to_hours(row.custom_total_hrs);
            let ot_day_hours = time_to_hours(row.custom_ot_day_hrs);
            let ot_night_hours = time_to_hours(row.custom_ot_night_hrs);
            let rest_hours = time_to_hours(row.custom_rest_hrs);

            total_working_hours += working_hours;
            total_ot_day_hours += ot_day_hours;
            total_ot_night_hours += ot_night_hours;
            total_rest_day_hours += rest_hours;

            console.log("Processing:", row.name);
            console.log("Working Hours:", working_hours);
            console.log("OT Day Hours:", ot_day_hours);
            console.log("OT Night Hours:", ot_night_hours);
            console.log("Rest Day Hours:", rest_hours);
        }

        console.log("TOTAL WORKING HOURS:", total_working_hours);
        console.log("TOTAL OT DAY HOURS:", total_ot_day_hours);
        console.log("TOTAL OT NIGHT HOURS:", total_ot_night_hours);
        console.log("TOTAL REST DAY HOURS:", total_rest_day_hours);

        // STEP 3: Update Total Hours in Salary Slip

        let hours_to_update = {
            custom_total_work_hrs: total_working_hours,
            custom_ot_day_hours: total_ot_day_hours,
            custom_ot_night_hours: total_ot_night_hours,
            custom_rest_day_hours: total_rest_day_hours
        };

        for (let field in hours_to_update) {

            await frappe.model.set_value(
                frm.doctype,
                frm.doc.name,
                field,
                hours_to_update[field]
            );

            console.log(field + " Updated:", hours_to_update[field]);
        }

        frm.refresh_field("custom_total_work_hrs");
        frm.refresh_field("custom_ot_day_hours");
        frm.refresh_field("custom_ot_night_hours");
        frm.refresh_field("custom_rest_day_hours");


        // STEP 4: Calculate Basic Pay using Salary Slip Hourly Rate

        let hourly_rate = flt(frm.doc.custom_rate_per_hour);

        console.log("Salary Slip Hourly Rate:", hourly_rate);

        let total_basic = total_working_hours * hourly_rate;

        console.log("Calculation:", total_working_hours, "x", hourly_rate);
        console.log("TOTAL BASIC PAY:", total_basic);


        // STEP 5: Find Basic component in Earnings

        let basic_row = (frm.doc.earnings || []).find(
            d => d.salary_component === "Basic"
        );

        if (!basic_row) {

            frappe.msgprint({
                title: "Basic Component Not Found",
                message: "Please check whether Basic exists in the Earnings table.",
                indicator: "red"
            });

            return;
        }


        // STEP 6: Update Basic amount

        await frappe.model.set_value(
            basic_row.doctype,
            basic_row.name,
            "amount",
            total_basic
        );

        frm.refresh_field("earnings");
        frm.dirty();

        console.log("Basic Pay Updated:", total_basic);


        // STEP 7: Fetch Oman Labour Rules multipliers

        console.log("STEP 7: Fetching Oman Labour Rules...");

        let rules_response = await frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Oman Labour Rules",
                name: "Oman Labour Rules"
            }
        });

        let rules = rules_response.message || {};

        let ot_day_multiplier = flt(rules.custom_overtime_day);
        let ot_night_multiplier = flt(rules.custom_overtime_night);
        let rest_multiplier = flt(rules.custom_rest_day__holiday_premium);

        console.log("OT Day Multiplier:", ot_day_multiplier);
        console.log("OT Night Multiplier:", ot_night_multiplier);
        console.log("Rest Day Multiplier:", rest_multiplier);


        // STEP 8: Calculate Basic Hourly Rate

        let basic_hourly_rate = flt(frm.doc.custom_rate_per_hour);

        console.log("Basic Hourly Rate:", basic_hourly_rate);


        // STEP 9: Calculate Overtime and Rest Day Pay

        let ot_day_hours = total_ot_day_hours;
        let ot_night_hours = total_ot_night_hours;
        let rest_day_hours = total_rest_day_hours;

        let ot_day_amount =
            basic_hourly_rate *
            ot_day_multiplier *
            ot_day_hours;

        let ot_night_amount =
            basic_hourly_rate *
            ot_night_multiplier *
            ot_night_hours;

        let rest_day_amount =
            basic_hourly_rate *
            rest_multiplier *
            rest_day_hours;

        console.log("OT Day Hours:", ot_day_hours);
        console.log("OT Day Amount:", ot_day_amount);

        console.log("OT Night Hours:", ot_night_hours);
        console.log("OT Night Amount:", ot_night_amount);

        console.log("Rest Day Hours:", rest_day_hours);
        console.log("Rest Day Amount:", rest_day_amount);


        // STEP 10: Update Earnings Components

        async function update_earning(component, amount) {

            let earning_row = (frm.doc.earnings || []).find(
                d => d.salary_component === component
            );

            if (!earning_row) {
                console.warn("Earning component not found:", component);
                return;
            }

            await frappe.model.set_value(
                earning_row.doctype,
                earning_row.name,
                "amount",
                amount
            );

            console.log(component + " Updated:", amount);
        }

        await update_earning("OT Day", ot_day_amount);

        await update_earning("OT Night", ot_night_amount);

        await update_earning(
            "Rest Day / Holiday Premium",
            rest_day_amount
        );


        // STEP 11: Refresh Earnings

        frm.refresh_field("earnings");
        frm.dirty();

        console.log("========== FINAL SALARY CALCULATION ==========");

        console.table([{
                Component: "Total Working Hours",
                Amount: total_working_hours
            },
            {
                Component: "OT Day Hours",
                Amount: total_ot_day_hours
            },
            {
                Component: "OT Night Hours",
                Amount: total_ot_night_hours
            },
            {
                Component: "Rest Day Hours",
                Amount: total_rest_day_hours
            },
            {
                Component: "Basic",
                Amount: total_basic
            },
            {
                Component: "OT Day",
                Amount: ot_day_amount
            },
            {
                Component: "OT Night",
                Amount: ot_night_amount
            },
            {
                Component: "Rest Day / Holiday Premium",
                Amount: rest_day_amount
            }
        ]);

        frappe.show_alert({
            message: "Working Hours, Basic Pay and Overtime Earnings Updated Successfully",
            indicator: "green"
        });

        console.log("========== SALARY CALCULATION COMPLETED ==========");

    } catch (error) {

        console.error("SALARY CALCULATION ERROR:", error);

        frappe.msgprint({
            title: "Calculation Error",
            message: error.message || "Check browser console for details.",
            indicator: "red"
        });
    }
}

frappe.listview_settings["Payroll Entry"] = {

    onload(listview) {

        listview.page.add_inner_button(
            "Export Payroll Excel",
            async function () {

                // Get only the Payroll Entry records currently loaded
                // in this List View.

                let payroll_entry_names = (listview.data || [])
                    .filter(row => row.name)
                    .map(row => row.name);

                payroll_entry_names = [
                    ...new Set(payroll_entry_names)
                ];

                if (!payroll_entry_names.length) {

                    frappe.msgprint(
                        "No Payroll Entry records are available in the current list."
                    );

                    return;
                }

                let button = listview.page.wrapper.find(
                    'button:contains("Export Payroll Excel")'
                );

                button.prop("disabled", true);

                try {

                    frappe.dom.freeze("Preparing Payroll Preview...");

                    let response = await frappe.call({
                        method: "tareqix_hrms.utils.payroll_export.get_payroll_preview",
                        args: {
                            payroll_entry_names: payroll_entry_names
                        }
                    });

                    let result = response.message;

                    if (!result || !result.rows || !result.rows.length) {

                        frappe.msgprint(
                            "No submitted payroll records found."
                        );

                        return;
                    }

                    show_payroll_preview(
                        result,
                        payroll_entry_names
                    );

                } catch (error) {

                    console.error("Payroll Preview Error:", error);

                    frappe.msgprint({
                        title: "Export Error",
                        message: error.message || "Unable to prepare payroll preview.",
                        indicator: "red"
                    });

                } finally {

                    frappe.dom.unfreeze();
                    button.prop("disabled", false);
                }
            }
        );
    }
};


function show_payroll_preview(data, payroll_entry_names) {

    let columns = data.columns || [];
    let rows = data.rows || [];

    function escape_html(value) {

        return String(value ?? "")
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");
    }

    let table_html = `
        <div style="
            margin-bottom: 15px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        ">
            <div>
                <b>Total Employees:</b> ${rows.length}
                <br>
                <span class="text-muted">
                    Only submitted Payroll Entry and Salary Slip records
                </span>
            </div>
        </div>

        <div style="
            overflow: auto;
            max-height: 65vh;
            border: 1px solid var(--border-color);
            border-radius: 6px;
        ">
            <table class="table table-bordered table-hover"
                   style="margin-bottom: 0; white-space: nowrap;">

                <thead>
                    <tr style="
                        position: sticky;
                        top: 0;
                        background: var(--control-bg);
                        z-index: 2;
                    ">
                        ${columns.map(column => `
                            <th>${escape_html(column)}</th>
                        `).join("")}
                    </tr>
                </thead>

                <tbody>
                    ${rows.map(row => `
                        <tr>
                            ${row.map(value => `
                                <td>${escape_html(value)}</td>
                            `).join("")}
                        </tr>
                    `).join("")}
                </tbody>

            </table>
        </div>
    `;

    let dialog = new frappe.ui.Dialog({

        title: "Payroll Excel Preview",

        size: "extra-large",

        fields: [
            {
                fieldtype: "HTML",
                fieldname: "payroll_preview"
            }
        ],

        primary_action_label: "Download Excel",

        primary_action: async function () {

            let download_button = dialog.get_primary_btn();

            download_button.prop("disabled", true);

            try {

                frappe.dom.freeze("Generating Excel File...");

                let response = await frappe.call({
                    method: "tareqix_hrms.utils.payroll_export.download_payroll_excel",
                    args: {
                        payroll_entry_names: payroll_entry_names
                    }
                });

                let result = response.message;

                if (!result || !result.file_data) {

                    frappe.throw("Excel file could not be generated.");
                }

                // Convert Base64 into Excel Blob
                let binary = atob(result.file_data);

                let bytes = new Uint8Array(binary.length);

                for (let i = 0; i < binary.length; i++) {
                    bytes[i] = binary.charCodeAt(i);
                }

                let blob = new Blob(
                    [bytes],
                    {
                        type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
                    }
                );

                let url = URL.createObjectURL(blob);

                let link = document.createElement("a");

                link.href = url;
                link.download = result.file_name || "Payroll_Export.xlsx";

                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);

                URL.revokeObjectURL(url);

                frappe.show_alert({
                    message: "Payroll Excel downloaded successfully.",
                    indicator: "green"
                });

            } catch (error) {

                console.error("Payroll Download Error:", error);

                frappe.msgprint({
                    title: "Download Error",
                    message: error.message || "Unable to download Excel file.",
                    indicator: "red"
                });

            } finally {

                frappe.dom.unfreeze();
                download_button.prop("disabled", false);
            }
        }
    });

    dialog.fields_dict.payroll_preview.$wrapper.html(table_html);

    // Cancel closes the preview dialog and returns to the List View.
dialog.set_secondary_action(function () {
    dialog.hide();
});

dialog.get_secondary_btn().text("Cancel");

    dialog.show();
}

