// =========================================================
// 2. SECTION VISIBILITY
// =========================================================

function toggle_stage_sections(frm) {

    const current_stage = frm.doc.current_stage;

    Object.entries(stage_sections).forEach(([stage, fieldname]) => {

        frm.toggle_display(
            fieldname,
            current_stage === "Onboarded" || stage === current_stage
        );

    });

}


// =========================================================
// 3. CONDITIONAL MANDATORY FIELD HANDLING
// =========================================================

function toggle_stage_mandatory(frm) {

    const current_stage = frm.doc.current_stage;

    let current_section = null;

    const stage_section_names = Object.values(stage_sections);

    frm.meta.fields.forEach(df => {

        if (df.fieldtype === "Section Break") {
            current_section = df.fieldname;
            return;
        }

        // Only change mandatory status for fields inside mapped stages
        if (!stage_section_names.includes(current_section)) {
            return;
        }

        const section_stage = Object.keys(stage_sections).find(
            stage => stage_sections[stage] === current_section
        );

        const is_active =
            current_stage === "Onboarded" ||
            section_stage === current_stage;

        // Preserve the original DocType mandatory setting
        if (df.__original_stage_reqd === undefined) {
            df.__original_stage_reqd = df.reqd ? 1 : 0;
        }

        const original_required = df.__original_stage_reqd;

        // Hidden stage: temporarily disable mandatory
        // Active stage: restore original mandatory setting
        const required_now = is_active && original_required;

        frm.toggle_reqd(df.fieldname, !!required_now);

        console.log(
            "[Visa and PRO Mandatory]",
            df.fieldname,
            "Section:",
            current_section,
            "Active:",
            is_active,
            "Original Required:",
            original_required,
            "Required Now:",
            !!required_now
        );

    });

    console.log(
        "[Visa and PRO] Current Stage:",
        current_stage
    );

}


// =========================================================
// 4. FINAL CLIENT-SIDE VALIDATION
// =========================================================

function validate_active_stage_fields(frm) {

    const current_stage = frm.doc.current_stage;

    let current_section = null;
    let missing_fields = [];

    const stage_section_names = Object.values(stage_sections);

    frm.meta.fields.forEach(df => {

        if (df.fieldtype === "Section Break") {
            current_section = df.fieldname;
            return;
        }

        if (!stage_section_names.includes(current_section)) {
            return;
        }

        const section_stage = Object.keys(stage_sections).find(
            stage => stage_sections[stage] === current_section
        );

        const is_active =
            current_stage === "Onboarded" ||
            section_stage === current_stage;

        if (!is_active) {
            return;
        }

        const original_required = df.__original_stage_reqd;

        if (!original_required) {
            return;
        }

        const value = frm.doc[df.fieldname];

        let is_missing = value === undefined ||
                         value === null ||
                         value === "";

        if (
            ["Table", "Table MultiSelect"].includes(df.fieldtype) &&
            !value?.length
        ) {
            is_missing = true;
        }

        if (is_missing) {
            missing_fields.push(df.label || df.fieldname);
        }

    });

    console.log(
        "[Visa and PRO Validation] Missing fields:",
        missing_fields
    );

    if (missing_fields.length) {

        frappe.msgprint({
            title: "Mandatory Fields Missing",
            indicator: "red",
            message:
                "Please complete the mandatory fields in the current stage:<br><br>" +
                missing_fields.map(field => "• " + frappe.utils.escape_html(field)).join("<br>")
        });

        frappe.validated = false;
    }

}


