// =========================================================

function show_create_worker_button(frm) {

    if (
        frm.doc.current_stage !== "Onboarded" ||
        frm.is_new()
    ) {
        return;
    }

    if (frm.doc.custom_created_employee) {

        frm.add_custom_button("View Employee", function() {

            frappe.set_route(
                "Form",
                "Employee",
                frm.doc.custom_created_employee
            );

        }, "Actions");

        return;
    }

    frm.add_custom_button("Create Worker", function() {

        create_worker(frm);

    }, "Actions");

}


// =========================================================
// 7. CREATE EMPLOYEE
// =========================================================

function create_worker(frm) {

    frappe.confirm(
        "Are you sure you want to create an Employee record from this Visa and PRO record?",

        function() {

            frappe.call({

                method: "create_worker_from_visa_and_pro",

                args: {
                    name: frm.doc.name
                },

                freeze: true,

                freeze_message: "Creating Employee record...",

                callback: function(r) {

                    if (r.message && r.message.employee) {

                        frappe.show_alert({
                            message: "Employee created successfully: " + r.message.employee,
                            indicator: "green"
                        });

                        frm.reload_doc();

                    }

                }

            });

        }
    );

}
